"""Migrated VAL-01 opportunity validation rules."""

from decimal import Decimal, InvalidOperation


def _value(row: dict | None, key: str):
    """Return a field value, treating absent fields as legacy empty strings."""
    if row is None:
        return ""
    return row.get(key, "")


def _is_empty(value) -> bool:
    return value is None or value == ""


def _nvl(value, default):
    return default if _is_empty(value) else value


def _number(value) -> Decimal:
    """Apply legacy numeric coercion: empty values compare as zero."""
    if _is_empty(value):
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _date_gte(left, right) -> bool:
    """Legacy date >= comparison, including the 00000000 no-value sentinel."""
    left = "" if left is None else str(left)
    right = "" if right is None else str(right)
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image in legacy VRL rule-file order."""
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amt = _number(_nvl(_value(record, "AMT"), 0))
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    # OPP-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (amt >= Decimal("0")):
        errors.append(_error("E3001", "Amount negative"))

    # OPP-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "W" and amt == Decimal("0"))
    ):
        errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "L" and lost_rsn == "")
    ):
        errors.append(_error("E3003", "Lost reason required"))

    # OPP-004: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "W" and close_dt == "00000000")
    ):
        errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005: UPDATE
    old_stat_cd = _value(old if event == "UPDATE" else None, "STAT_CD")
    if event == "UPDATE" and not (
        not (old_stat_cd == "W" and stat_cd != "W")
    ):
        errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006: INSERT, UPDATE
    stage_is_consistent = (
        (stat_cd == "P" and stage_pct == Decimal("10"))
        or (stat_cd == "Q" and stage_pct == Decimal("25"))
        or (stat_cd == "N" and stage_pct == Decimal("60"))
        or (stat_cd == "W" and stage_pct == Decimal("100"))
        or (stat_cd == "L" and stage_pct == Decimal("0"))
    )
    if event in ("INSERT", "UPDATE") and not stage_is_consistent:
        errors.append(_error("E3006", "Stage percent inconsistent with status"))

    # OPP-007: INSERT
    if event == "INSERT" and not (
        close_dt == "00000000" or _date_gte(close_dt, today)
    ):
        errors.append(_error("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
